package com.bank.fee.service;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Computes every possible result of a fee formula under all groupings.
public class ExpressionService {
    private static final Logger log = Logger.getLogger(ExpressionService.class.getName());

    private final Map<String, List<BigDecimal>> memo = new HashMap<>();

    public List<BigDecimal> allResults(String expr) {
        if (memo.containsKey(expr)) {
            return memo.get(expr); // reuse an already-solved sub-formula
        }
        List<BigDecimal> results = new ArrayList<>();
        boolean hasOperator = false;
        for (int i = 0; i < expr.length(); i++) {
            char ch = expr.charAt(i);
            if (ch == '+' || ch == '-' || ch == '*') {
                hasOperator = true;
                // Split: evaluate left and right sub-formulas.
                List<BigDecimal> left = allResults(expr.substring(0, i));
                List<BigDecimal> right = allResults(expr.substring(i + 1));
                for (BigDecimal l : left) {
                    for (BigDecimal r : right) {
                        results.add(apply(l, r, ch));
                    }
                }
            }
        }
        if (!hasOperator) {
            results.add(new BigDecimal(expr)); // base case: a plain number
        }
        memo.put(expr, results);
        log.fine(() -> "Sub-formula '" + expr + "' yields " + results);
        return results;
    }

    private BigDecimal apply(BigDecimal l, BigDecimal r, char op) {
        switch (op) {
            case '+': return l.add(r);
            case '-': return l.subtract(r);
            case '*': return l.multiply(r);
            default: throw new IllegalArgumentException("Bad operator " + op);
        }
    }
}
