package com.bank.fee;

import com.bank.fee.service.ExpressionService;
import java.util.logging.Logger;

public class ExpressionApplication {
    private static final Logger log = Logger.getLogger(ExpressionApplication.class.getName());

    public static void main(String[] args) {
        ExpressionService service = new ExpressionService();
        // Fee formula 2*3-4 can group as (2*3)-4=2 or 2*(3-4)=-2.
        log.info("NBI possible fee totals for '2*3-4': " + service.allResults("2*3-4"));
    }
}
